package com.shopl.sdg.mcp.examples

import androidx.annotation.DrawableRes
import androidx.compose.runtime.Composable
import com.shopl.sdg.template.empty.SDGEmpty

/** 조회 결과의 상태입니다. 조회·재시도 정책은 호출 화면에서 결정합니다. */
enum class ListExampleState {
    LOADING,
    CONTENT,
    EMPTY,
    ERROR,
}

/** 로딩·목록·오류 콘텐츠는 앱의 기존 UI를 연결합니다. SDG는 빈 상태 표시를 담당합니다. */
@Composable
fun ListStatesExample(
    state: ListExampleState,
    @DrawableRes emptyIllustration: Int,
    emptyTitle: String,
    loading: @Composable () -> Unit,
    content: @Composable () -> Unit,
    error: @Composable () -> Unit,
) {
    when (state) {
        ListExampleState.LOADING -> loading()
        ListExampleState.CONTENT -> content()
        ListExampleState.EMPTY -> SDGEmpty(illustrationResId = emptyIllustration, title = emptyTitle)
        ListExampleState.ERROR -> error()
    }
}

package com.shopl.sdg.mcp.examples

import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.runtime.Composable
import com.shopl.sdg.component.radio.SDGRadio
import com.shopl.sdg.component.radio.model.SDGRadioSelectedBackgroundColor
import com.shopl.sdg.component.radio.model.SDGRadioSize
import com.shopl.sdg.component.radio.model.SDGRadioState
import kotlinx.collections.immutable.PersistentList

/** ID는 항목별로 고유해야 합니다. 라벨과 선택 상태는 호출 화면이 제공합니다. */
@Composable
fun SingleChoiceExample(
    optionIds: PersistentList<String>,
    selectedId: String?,
    onSelect: (String) -> Unit,
    label: @Composable (String) -> Unit,
) {
    Column {
        optionIds.forEach { id ->
            Row {
                SDGRadio(
                    state = if (id == selectedId) SDGRadioState.SELECTED else SDGRadioState.DEFAULT,
                    selectedBackgroundColor = SDGRadioSelectedBackgroundColor.NORMAL,
                    size = SDGRadioSize.MEDIUM,
                    onClick = { onSelect(id) },
                )
                label(id)
            }
        }
    }
}

package com.shopl.sdg.mcp.examples

import androidx.compose.foundation.layout.Column
import androidx.compose.runtime.Composable
import com.shopl.sdg.component.tab.fixed.SDGFixedTab
import com.shopl.sdg.component.tab.fixed.SDGFixedTabBaselineDivider
import com.shopl.sdg.component.tab.fixed.SDGFixedTabOption
import com.shopl.sdg_common.foundation.SDGColor

/** 두 탭의 조합 예제입니다. selectedTab은 0 또는 1이며 상태 보존 정책은 호출 화면이 결정합니다. */
@Composable
fun TabsExample(
    firstLabel: String,
    secondLabel: String,
    selectedTab: Int,
    onSelectTab: (Int) -> Unit,
    firstContent: @Composable () -> Unit,
    secondContent: @Composable () -> Unit,
) {
    Column {
        SDGFixedTab(
            option = SDGFixedTabOption.TwoOption(listOf(firstLabel, secondLabel)),
            selectedTab = selectedTab,
            onTabClick = onSelectTab,
            unselectedTabUnderLineColor = SDGColor.Neutral200,
            baselineDivider = SDGFixedTabBaselineDivider.Hidden,
        )
        when (selectedTab) {
            0 -> firstContent()
            1 -> secondContent()
        }
    }
}

