/**
 * SDG 샘플의 속성(Type, Spec 등)을 Large / Only Text 탭으로 표시하고 선택 인덱스를 전달합니다.
 *
 * @param tabTitle 탭의 타이틀
 * @param tabs 탭 선택가능 값
 */
@Composable
internal fun <T> SDGSampleBaseTab(
    tabTitle: String,
    tabs: ImmutableList<SDGSampleBaseTabItem<T>>,
    selectedTabIndex: Int,
    onTabClick: (Int) -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(SDGSpacing.Spacing8)
    ) {
        SDGText(
            text = tabTitle,
            textColor = SDGColor.Neutral350,
            typography = SDGTypography.Body3SB
        )
        SDGScrollTab(
            style = SDGScrollTabStyle.OnlyText,
            size = SDGScrollTabSize.Large,
            titles = tabs.map { it.title }.toPersistentList(),
            selectedTab = selectedTabIndex,
            onTabClick = onTabClick,
            backgroundColor = SDGColor.Transparent
        )
    }
}

