            label = "옵션명이 길어지면 아이콘과 상단 정렬되고 사용 가능한 영역에서 줄바꿈으로 전체 내용을 노출합니다.",
            state = state,
            selectType = selectType,
            onClick = {},
        )
    }
}

@Composable
internal fun CustomHistoryScreen(
    onClickBack: () -> Unit,
    onClickMenu: () -> Unit,
) {
    SDGSampleBaseScaffold(
        name = TemplateScene.CustomHistory.displayLabel,
        description = "Dot과 Line 타임라인을 기반으로 다양한 이력과 진행 흐름을 커스텀 구성하는 템플릿",
        bodyContent = { CustomHistoryContent() },
        onClickBack = onClickBack,
        onClickMenu = onClickMenu,
        usageGuideLinesContent = {
            SDGSampleBaseGuideLinesContent(
                guideLineDescriptions = persistentListOf(
                    "History의 Width는 정해진 가용 범위 내에서 가변합니다.",
                ),
            )
        },
    )
}

@Composable
private fun CustomHistoryContent() {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(
                horizontal = SDGSpacing.Spacing16,
                vertical = SDGSpacing.Spacing40,
            ),
    ) {
        SDGCustomHistory(
            position = SDGCustomHistoryPosition.TOP,
            dotColor = SDGColor.Primary300,
            header = {
                SampleHistoryHeader(
                    stepLabel = "1단계",
                    showDescription = true
                )
            },
            body = { SampleHistoryBody("근무 일정: 09:00 - 18:00") },
        )

        SDGCustomHistory(
            position = SDGCustomHistoryPosition.MIDDLE,
            dotColor = SDGColor.Primary300,
            header = {
                SampleHistoryHeader(
                    stepLabel = "2단계",
                    showDescription = true

                )
            },
            body = {
                SampleHistoryBody(
                    text = "출근 시간이 09:00에서 10:00으로 변경되었습니다.",
                    contentPadding = PaddingValues(
                        horizontal = SDGSpacing.Spacing8,
                        vertical = SDGSpacing.Spacing8,
                    ),
                )
            },
        )

        SDGCustomHistory(
            position = SDGCustomHistoryPosition.MIDDLE,
            dotColor = SDGColor.Primary300,
            header = {
                SampleHistoryHeader(
                    stepLabel = "3단계",
                    showDescription = false
                )
            },
            body = {
                SampleHistoryBody("담당자: 홍길동\n처리 예정: 오늘 18:00")
            },
        )

        SDGCustomHistory(
            position = SDGCustomHistoryPosition.LAST,
            dotColor = SDGColor.Primary300,
            header = {
                SampleHistoryHeader(
                    stepLabel = "4단계",
                    showDescription = true
                )
            },
            body = null,
        )
    }
}

@Composable
private fun SampleHistoryHeader(
    stepLabel: String,
    showDescription: Boolean
) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(
            verticalArrangement = spacedBy(Spacing4),
            modifier = Modifier.weight(1f, true)
        ) {
            Row(
                horizontalArrangement = spacedBy(Spacing4),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                SDGImage(
                    resId = R.drawable.ic_common_checkbold,
                    color = SDGColor.Primary300,
                    modifier = Modifier.size(18.dp),
                )
                SDGText(
                    text = stepLabel,
                    typography = SDGTypography.Body1SB,
                    textColor = SDGColor.Neutral700
                )
                SDGBoxBadge(
                    label = "승인",
                    style = SDGBoxBadgeStyle.Solid,
                    fontWeight = SDGBoxBadgeFontWeight.Normal,
                    backgroundColor = SDGColor.Neutral150,
                    labelColor = SDGColor.Neutral700,
                    leftIc = null,
                    rightIc = null
                )
            }
            if (showDescription) {
                SDGText(
                    text = "설명입니다.",
                    typography = SDGTypography.Body2R,
                    textColor = SDGColor.Neutral700
                )
            }
        }
        SDGImage(
            resId = R.drawable.ic_common_next_s,
            color = SDGColor.Neutral600,
            modifier = Modifier
                .padding(horizontal = Spacing12)
                .size(14.dp),
        )
    }
}

@Composable
private fun SampleHistoryBody(
    text: String,
    contentPadding: PaddingValues = PaddingValues(Spacing12),
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(SDGColor.Neutral150, SDGCornerRadius.BoxRadius.Radius8)
            .padding(contentPadding),
    ) {
        SDGText(
            text = text,
            typography = SDGTypography.Body2R,
            textColor = SDGColor.Neutral700,
        )
    }
}

/**
 * SDG Sample App - Navigation - Text Navi
 *
 * @see <a href="https://www.figma.com/design/qWVshatQ9eqoIn4fdEZqWy/SDG?node-id=30016-9273&m=dev">Figma</a>
 */
@Composable
internal fun TextNaviScreen(
    onClickBack: () -> Unit,
    onClickMenu: () -> Unit,
) {
    var actionClickCount by remember { mutableIntStateOf(0) }

    SDGSampleBaseScaffold(
        name = TemplateScene.Navigation.TextNavi.displayLabel,
        description = "화면 상단에서 현재 위치를 나타내는 타이틀과 화면 이동, 우측 주요 실행 기능을 제공하는 내비게이션 컴포넌트",
        onClickBack = onClickBack,
        onClickMenu = onClickMenu,
        bodyContent = {
            TextNaviContent(
                actionClickCount = actionClickCount,
                onClickBack = onClickBack,
                onClickAction = { actionClickCount++ },
            )
        },
        usageGuideLinesContent = {
            SDGSampleBaseGuideLinesContent(
                guideLineDescriptions = persistentListOf(
                    "Status Bar 영역을 제외한 모바일 화면의 최상단에 배치합니다.",
                    "모든 구성 요소는 세로 중앙 정렬합니다.",
                    "Sub Label 문구는 동사형 단어로 짧게 작성합니다.",
                    "Label이 길 때 Sub Label은 줄이지 않고 Label이 말줄임 처리됩니다. 긴 타이틀과 긴 Sub Label을 함께 쓰지 않습니다.",
                ),
            )
        },
    )
}

